verus! {

    /// Given two equal‐length arrays `a` and `b` of signed 8-bit integers,
    /// produce a boolean array `result` of the same length such that
    /// for every index i,
    ///   result[i] == true  ⇔  (a[i] as int) ≠ (b[i] as int).
    fn not_equal(a: Vec<i8>, b: Vec<i8>) -> (result: Vec<bool>)
        requires
            // The inputs must have the same length.
            a.len() == b.len()
        ensures
            // The output has the same length as the inputs.
            result.len() == a.len()
        ensures
            // Pointwise correctness: at each valid index i, result[i] records
            // whether a[i] and b[i] differ (when viewed as mathematical integers).
            forall |i: usize| i < a.len() ==> result[i] == (a[i] as int != b[i] as int)
    {
        let mut result: Vec<bool> = Vec::new();
        let mut i: usize = 0;
        // We build up `result` one index at a time.
        while i < a.len()
            invariant  i <= a.len()
            invariant  result.len() == i
            invariant  forall |j: usize| j < i
                         ==> result[j] == (a[j] as int != b[j] as int)
        {
            let diff: bool = a[i] as int != b[i] as int;
            result.push(diff);
            i += 1;
        }
        result
    }

}